/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'feedback_sentiment',
		value: event.payload.value
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const feedbackSentiment = event.payload.value;
	const feedbackSentimentOptions = api.state.feedback_sentiment_options;
	feedbackSentimentOptions.forEach(option => {
		if (feedbackSentiment === option.id) {
            option["checked"] = true;
		} else {
			delete option.checked;
		}
	});
	return {
		propName: 'feedback_sentiment_options',
		value: feedbackSentimentOptions
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if (api.state.feedback_sentiment === 'positive') {
        return {
            event: 'Click nlq feedback',
            value: {
                'Sentiment': 'positive',
                'FbCatTable': 'NA',
                'FbCatRelationship': 'NA',
                'FbCatRelatedtable': 'NA',
                'FbCatFilter': 'NA',
                'FbCatOther': 'NA'
            }
        };
    }
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const selectedCategory = event.payload;
	const feedbackCategoriesOptions = api.state.feedback_categories_options;
	feedbackCategoriesOptions.find(option => option.itemId === selectedCategory.itemId)['checked'] = selectedCategory.checked;
	return {
		propName: 'feedback_categories_options',
		value: feedbackCategoriesOptions
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'feedback_details',
		value: event.payload.value
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let sentiment = api.state.feedback_sentiment;
    if (sentiment === 'negative') {
        const categoryArray = api.state.feedback_categories_options
            .filter(option => option.checked)
            .map(selected => selected.itemId);
        let isTable = categoryArray.includes('table') ? 'true' : 'false';
        let isRelationship = categoryArray.includes('relationship') ? 'true' : 'false';
        let isRelatedtable = categoryArray.includes('relatedtable') ? 'true' : 'false';
        let isFilter = categoryArray.includes('filter') ? 'true' : 'false';
        let isOther = categoryArray.includes('other') ? 'true' : 'false';
        return {
            event: 'Click nlq feedback',
            value: {
                'Sentiment': 'negative',
                'FbCatTable': isTable,
                'FbCatRelationship': isRelationship,
                'FbCatRelatedtable': isRelatedtable,
                'FbCatFilter': isFilter,
                'FbCatOther': isOther
            }
        };
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let action = event.payload.wrappedAction;
    let actionType = '';
    if (action === 'DA#EXPORT_MODAL') {
        actionType = 'export';
    } else if (action === 'open_in_query_builder') {
        actionType = 'view QB';
    } else if (action === 'load_all_results') {
        actionType = 'load all';
    } else if (action === 'load_more_results') {
        actionType = 'load more';
    }

    return {
        event: 'Click nlq result action',
        value: {
            'Type': actionType
        }
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		route: 'manual-create-ci',
		fields: null,
		params: { sysClassName: api.context.props.table, ts: Date.now(), parentCiRefQuery: null},
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: 'current',
		external: null,
		navigationOptions: null
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let className = '';
    const {
        recordTable
    } = event.payload;

    if (recordTable) {
        className = recordTable;
    }
    return {
        event: "Click nlq result record",
        value: {
            'Class': className
        }
    };
}
